sed -i '/export default function DashboardStudent() {/a \
  const [modalConfig, setModalConfig] = useState<{\n    isOpen: boolean;\n    title: string;\n    message: string;\n    type: "confirm" | "alert" | "danger";\n    onConfirm?: () => void;\n    confirmText?: string;\n  }>({\n    isOpen: false,\n    title: "",\n    message: "",\n    type: "alert",\n  });\n\n  const showAlert = (\n    title: string,\n    message: string,\n    type: "alert" | "danger" = "alert",\n  ) => {\n    setModalConfig({ isOpen: true, title, message, type });\n  };\n\n  const showConfirm = (\n    title: string,\n    message: string,\n    onConfirm: () => void,\n    confirmText = "Proses",\n  ) => {\n    setModalConfig({\n      isOpen: true,\n      title,\n      message,\n      type: "confirm",\n      onConfirm,\n      confirmText,\n    });\n  };\n' src/pages/DashboardStudent.tsx
